 AS r(
    district text,name text,address_line text,category text,phone text,
    tax_code text,source_key text,source_url text,evidence_level text,
    verification_note text
 )
),
 inserted AS (
 INSERT INTO public.field_prospects (
  id,owner_sub,name,address_line,province,district,
  category,phone,tax_code,note,status,source_kind,
  research_source_key,research_source_url,research_batch
 )
 SELECT
  (substr(r.digest,1,8)||'-'||substr(r.digest,9,4)||'-5'||substr(r.digest,14,3)||'-8'||substr(r.digest,18,3)||'-'||substr(r.digest,21,12))::uuid,
  'ef943de4-18f7-49ef-8340-eefb18855534',r.name,r.address_line,'Bến Tre',r.district,
  r.category,r.phone,r.tax_code,
  'Dữ liệu nghiên cứu công khai; chưa ghé và chưa có GPS xác minh. '||
   coalesce(r.verification_note,'')||' Nguồn: '||r.source_url,
  'new','manual',r.source_key,r.source_url,
  '2026-11-21-ben-tre-8-districts-stationery-01'
 FROM raw r
 WHERE r.category IN ('nha_sach','van_phong_pham')
  AND r.source_url LIKE 'https://%'
  AND r.district IN ('Huyện Ba Tri','Huyện Bình Đại','Huyện Châu Thành',
    'Huyện Chợ Lách','Huyện Giồng Trôm','Huyện Mỏ Cày Bắc',
    'Huyện Mỏ Cày Nam','Huyện Thạnh Phú')
  AND NOT EXISTS (
   SELECT 1 FROM public.customers c
   WHERE c.province='Bến Tre' AND c.district=r.district
   AND (
    (r.tax_code IS NOT NULL AND regexp_replace(coalesce(c.vat_tax_code,''),'[^0-9]','','g')=r.tax_code
      AND lower(btrim(c.address_line))=lower(btrim(r.address_line)))
    OR (lower(btrim(c.name))=lower(btrim(r.name))
      AND lower(btrim(c.address_line))=lower(btrim(r.address_line)))
   )
  )
  AND NOT EXISTS (
   SELECT 1 FROM public.field_prospects p
   WHERE p.province='Bến Tre' AND p.district=r.district
    AND (
      p.research_source_key=r.source_key
      OR (lower(btrim(p.name))=lower(btrim(r.name))
         AND lower(btrim(p.address_line))=lower(btrim(r.address_line)))
    )
  )
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING id,name,district,category
)
SELECT id,name,district,category FROM inserted ORDER BY district,name;
